// N8N-SINTEL-02 FASE 7/12: valida la firma HMAC-SHA256 igual que
// apps/services/integration_events/tasks.py::_firmar() del lado SINTEL.
// Nunca procesar un evento cuya firma no coincide -- podria no venir de
// SINTEL en absoluto (Fase 14, 'webhook sin proteccion').
const crypto = require('crypto');

const secret = $env.N8N_WEBHOOK_SECRET || '';
const rawBody = JSON.stringify($input.first().json, Object.keys($input.first().json).sort());
// SINTEL firma con json.dumps(event, sort_keys=True) -- mismo criterio
// de serializacion (claves ordenadas) para que el HMAC coincida byte a
// byte. Si el body ya no es exactamente ese, la firma no calzara nunca
// -- revisar contra tasks.py si esto falla sistematicamente.
const received = $input.first().headers['x-sintel-signature'] || '';
const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');

const valido = expected === received;

return [{ json: { ...$input.first().json, _firma_valida: valido, _event_id: $input.first().json.event_id } }];

// N8N-SINTEL-02 FASE 11: idempotencia real del lado n8n -- usa
// almacenamiento estatico del propio workflow (persiste entre
// ejecuciones, nativo de n8n, sin credencial/DB adicional). event_id
// es el identificador real (DomainEvent.event_id, uuid4 generado por
// SINTEL) -- nunca se reusa segun el contrato ya verificado en
// tests/services/integration_events/test_contracts.py.
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenEventIds) staticData.seenEventIds = [];

const eventId = $input.first().json._event_id;
const yaVisto = staticData.seenEventIds.includes(eventId);

if (!yaVisto) {
  staticData.seenEventIds.push(eventId);
  // Evita crecimiento sin limite -- conserva los ultimos 5000 event_id.
  if (staticData.seenEventIds.length > 5000) {
    staticData.seenEventIds = staticData.seenEventIds.slice(-5000);
  }
}

return [{ json: { ...$input.first().json, _ya_procesado: yaVisto } }];

